static const uint16_t* const auraPaletteList[AURA_NUM_FACES] = {
  auraPalette0,auraPalette1,auraPalette2,auraPalette3,auraPalette4,auraPalette5,auraPalette6
};
static const uint8_t* const auraRLEList[AURA_NUM_FACES] = {
  auraRLE0,auraRLE1,auraRLE2,auraRLE3,auraRLE4,auraRLE5,auraRLE6
};

// Only 6,144 bytes for the decoded sprite + 192 bytes for the SPI scanline.
// RLE and palettes are stored in flash via PROGMEM.
static uint8_t auraIndices[AURA_SW * AURA_SH];
static uint8_t auraRow[AURA_SW * 2];
static uint16_t auraCurrentPalette[128];
static int8_t auraCachedFace = -1;
static int8_t auraRenderedFace = -1;

// Legacy face ID mapping from the existing aura_core.ino:
// 0=happy, 1=okay, 2=sad, 3=thirsty, 4=dizzy, 5=needlight, 6=neutral.
static uint8_t auraLegacyToArt(int legacy) {
  switch (legacy) {
    case 0: return 0;
    case 1: return 1;
    case 2: return 5;
    case 3: return 3;
    case 4: return 6;
    case 5: return 4;
    case 6: return 2;
    default: return 1;
  }
}

static void auraLoadArt(uint8_t art) {
  if (art >= AURA_NUM_FACES || auraCachedFace == (int8_t)art) return;
  const uint16_t* palette = auraPaletteList[art];
  for (int i = 0; i < 128; ++i) auraCurrentPalette[i] = pgm_read_word(palette + i);
  const uint8_t* src = auraRLEList[art];
  uint16_t offset = 0;
  uint16_t pos = 0;
  while (pos < AURA_SW * AURA_SH) {
    uint8_t count = pgm_read_byte(src + offset++);
    uint8_t index = pgm_read_byte(src + offset++);
    if (count == 0) break;
    for (uint8_t j = 0; j < count && pos < AURA_SW * AURA_SH; ++j)
      auraIndices[pos++] = index;
  }
  auraCachedFace = art;
}

static uint16_t auraBgr565(uint8_t r, uint8_t g, uint8_t b) {
  return (uint16_t)((((uint16_t)b >> 3) << 11) | (((uint16_t)g >> 2) << 5) | (r >> 3));
}
static uint16_t auraTint565(uint16_t v, uint8_t r, uint8_t g, uint8_t b, uint8_t amount) {
  uint8_t br = (v & 31) << 3;
  uint8_t bg = ((v >> 5) & 63) << 2;
  uint8_t bb = ((v >> 11) & 31) << 3;
  br = ((uint16_t)br*(255-amount) + (uint16_t)r*amount)/255;
  bg = ((uint16_t)bg*(255-amount) + (uint16_t)g*amount)/255;
  bb = ((uint16_t)bb*(255-amount) + (uint16_t)b*amount)/255;
  return auraBgr565(br,bg,bb);
}

// Extra display-only timers: none of the existing servo/mic/mood timers change.
enum AuraScene : uint8_t { AURA_IDLE, AURA_WATER_FILL, AURA_WATER_HOLD,
  AURA_WATER_DRAIN, AURA_SUN_RAY, AURA_SUN_GROW, AURA_SUN_HAPPY,
  AURA_TALK, AURA_WINK, AURA_LOOK, AURA_THINK, AURA_WIGGLE,
  AURA_EXCITED, AURA_SLEEP };
static AuraScene auraScene = AURA_IDLE;
static unsigned long auraSceneStart = 0;
static unsigned long auraLastActivity = 0;
static unsigned long auraLastFrame = 0;
static uint8_t auraSceneFace = 1;
static const unsigned long AURA_FILL_MS = 1800;
static const unsigned long AURA_HOLD_MS = 10000;  // approved 10-second water hold
static const unsigned long AURA_DRAIN_MS = 1800;
static const unsigned long AURA_IDLE_SLEEP_MS = 600000; // 10-minute idle sleep

static bool auraSceneIsWater() {
  return auraScene==AURA_WATER_FILL || auraScene==AURA_WATER_HOLD || auraScene==AURA_WATER_DRAIN;
}
static bool auraAnimationActive() { return auraScene != AURA_IDLE; }
static void auraStartScene(AuraScene scene) {
  if (auraSceneIsWater() && scene!=AURA_WATER_FILL) return; // watering priority
  auraScene = scene;
  auraSceneStart = millis();
  auraLastActivity = millis();
  auraLastFrame = 0;
}
static void auraStartWater() { auraStartScene(AURA_WATER_FILL); }
static void auraStartSunlight() { if (!auraSceneIsWater()) auraStartScene(AURA_SUN_RAY); }
static void auraStartTalking() { auraStartScene(AURA_TALK); }
static void auraStartWink() { auraStartScene(AURA_WINK); }
static void auraStartLook() { auraStartScene(AURA_LOOK); }
static void auraStartThink() { auraStartScene(AURA_THINK); }
static void auraStartWiggle() { auraStartScene(AURA_WIGGLE); }
static void auraStartExcited() { auraStartScene(AURA_EXCITED); }
static void auraStartSleeping() { auraStartScene(AURA_SLEEP); }

static bool auraInsideLeftEye(int x, int y) { return x>=24 && x<=39 && y>=25 && y<=40; }
static bool auraInsideRightEye(int x, int y) { return x>=58 && x<=73 && y>=25 && y<=40; }
static bool auraArchPixel(int x, int y, int left) {
  int dx = x-(left?27:62);
  return (dx==0 && y>=34 && y<=35) || (dx==1 && y>=31 && y<=34) ||
    (dx==2 && y>=29 && y<=31) || (dx>=3 && dx<=7 && y>=28 && y<=29) ||
    (dx==8 && y>=29 && y<=31) || (dx==9 && y>=31 && y<=34) ||
    (dx==10 && y>=34 && y<=35);
}
static bool auraArrowPixel(int x, int y, bool isLeft) {
  int dx = x - (isLeft?27:63);
  // Left arrow is >, right arrow is <.
  int target = isLeft ? 9-abs(y-33)*2 : 1+abs(y-33)*2;
  return y>=29 && y<=37 && dx>=0 && dx<=10 && abs(dx-target)<=1;
}

// The OLED takes full RGB565 scanlines. We recolour each pixel before sending,
// so blue water/yellow light can overlay the exact approved base artwork.
static void auraRenderArt(uint8_t art, uint8_t eyeMode=0, uint8_t effect=0, uint16_t progress=0,
                          uint8_t lookPhase=0) {
  if (art >= AURA_NUM_FACES) return;
  auraLoadArt(art);
  auraRenderedFace = art;
  unsigned long now = millis();
  int waveBase = 64 - (64L * progress)/1000;
  int waveOffset = (now/160)%24;
  display.goTo(0,0);
  display.startData();
  for (int y=0; y<AURA_SH; ++y) {
    for (int x=0; x<AURA_SW; ++x) {
      int ox=x,oy=y;
      if (effect==4 && y>=7 && y<=24 && x>=15 && x<=80) {
        oy = y + ((now/220)%2 == 0 ? 1 : -1);
        if (oy<0) oy=0; if (oy>=AURA_SH) oy=AURA_SH-1;
      }
      uint16_t color = auraCurrentPalette[auraIndices[oy*AURA_SW+ox]];
      bool left=auraInsideLeftEye(x,y), right=auraInsideRightEye(x,y);
      if (eyeMode==1 && (left||right)) {
        color=auraArchPixel(x,y,left)?auraBgr565(255,255,255):0;
      } else if (eyeMode==2 && left) {
        color=auraArrowPixel(x,y,true)?auraBgr565(255,255,255):0;
      } else if (eyeMode==3 && (left||right)) {
        color=auraArrowPixel(x,y,left)?auraBgr565(255,255,255):0;
      } else if (eyeMode==4 && (left||right)) {
        int dx = (lookPhase%4==0?-2:lookPhase%4==1?2:lookPhase%4==2?1:-1);
        int dy = (lookPhase%4==0?-1:lookPhase%4==1?-1:lookPhase%4==2?1:1);
        int srcX=x-dx,srcY=y-dy;
        if ((left && auraInsideLeftEye(srcX,srcY)) || (right && auraInsideRightEye(srcX,srcY)))
          color=auraCurrentPalette[auraIndices[srcY*AURA_SW+srcX]];
        else color=0;
      } else if (eyeMode==5 && (left||right)) {
        color=auraArchPixel(x,y,left)?auraBgr565(255,255,255):0;
      }
      if (effect==1 || effect==2) {
        int zz=(x+waveOffset)%24;
        int wav = (zz<12 ? zz : 24-zz)/4-1;
        int surface = waveBase + wav;
        if (effect==2) surface=-3;
        if (y>=surface) {
          color=auraTint565(color,23,175,220,100);
          if (effect==1 && abs(y-surface)<=1) color=auraTint565(color,181,248,255,170);
          if ((x==15 && y==46)||(x==29 && y==55)||(x==77 && y==42))
            color=auraBgr565(186,244,255);
        }
      } else if (effect==3) {
        // Golden diagonal sunlight: narrow -> broad -> full, without hard edges.
        int mid=92-(y*3)/4;
        int width=progress<330?5:progress<720?19:55;
        int dist=abs(x-mid);
        if (dist<width && (progress>720 || y<56)) {
          uint8_t opacity=(uint8_t)((width-dist)*105/width);
          if (progress>720) opacity= (uint8_t)(28+opacity);
          color=auraTint565(color,255,215,10,opacity);
        }
      }
      auraRow[2*x]=(uint8_t)(color>>8);
      auraRow[2*x+1]=(uint8_t)(color&0xFF);
    }
    display.writeBuffer(auraRow,AURA_SW*2);
  }
  display.endTransfer();
  // Retain vivid sparkles above the blue tint during the water celebration.
  if (effect==2) {
    display.drawLine(10,20,10,32,255,235,0);
    display.drawLine(5,26,15,26,255,235,0);
    display.drawLine(87,23,87,33,255,235,0);
    display.drawLine(83,28,91,28,255,235,0);
  }
  if (effect==3 && progress>720) {
    display.drawRect(82,8,7,7,true,255,215,0);
  }
  if (effect==5) { // Talk: yellow sound lines
    display.drawLine(5,29,11,31,255,235,0);
    display.drawLine(5,23,11,26,255,235,0);
    display.drawLine(85,26,91,23,255,235,0);
    display.drawLine(85,31,91,29,255,235,0);
  }
  if (effect==6) { // Think: question mark
    display.drawRect(83,17,6,2,true,255,235,0);
    display.drawRect(88,19,2,4,true,255,235,0);
    display.drawRect(84,23,4,2,true,255,235,0);
    display.drawRect(84,27,2,2,true,255,235,0);
  }
  if (effect==7) { // Sleep: two blue Zs
    display.drawLine(82,17,89,17,85,210,255);
    display.drawLine(89,17,82,24,85,210,255);
    display.drawLine(82,24,89,24,85,210,255);
    display.drawLine(88,9,93,9,85,210,255);
    display.drawLine(93,9,88,14,85,210,255);
    display.drawLine(88,14,93,14,85,210,255);
  }
  if (effect==8) { // Wiggle: white motion accents
    display.drawLine(8,24,5,29,255,255,255);
    display.drawLine(88,24,91,29,255,255,255);
  }
}

static void auraDrawLegacyFace(int face, bool blink) {
  uint8_t art=auraLegacyToArt(face);
  auraSceneFace=art;
  auraRenderArt(art,blink?1:0);
}

// Called in loop: performs only display animation, never delays servo/BLE/accel.
static void auraTick() {
  unsigned long now=millis();
  if (auraScene==AURA_IDLE) {
    if (now-auraLastActivity >= AURA_IDLE_SLEEP_MS) auraStartSleeping();
    else return;
  }
  // Falls/shakes override decorative scenes; keep existing dizzy timer intact.
  if (now < dizzyUntil) {
    auraScene=AURA_IDLE;
    auraLastActivity=now;
    lastFace=-1;
    return;
  }
  unsigned long elapsed=now-auraSceneStart;
  if (auraScene==AURA_WATER_FILL && elapsed>=AURA_FILL_MS) {
    auraScene=AURA_WATER_HOLD; auraSceneStart=now; elapsed=0;
  } else if (auraScene==AURA_WATER_HOLD && elapsed>=AURA_HOLD_MS) {
    auraScene=AURA_WATER_DRAIN; auraSceneStart=now; elapsed=0;
  } else if (auraScene==AURA_WATER_DRAIN && elapsed>=AURA_DRAIN_MS) {
    auraScene=AURA_IDLE; auraLastActivity=now; lastFace=-1; return;
  } else if (auraScene==AURA_SUN_RAY && elapsed>=700) {
    auraScene=AURA_SUN_GROW; auraSceneStart=now; elapsed=0;
  } else if (auraScene==AURA_SUN_GROW && elapsed>=1100) {
    auraScene=AURA_SUN_HAPPY; auraSceneStart=now; elapsed=0;
  } else if (auraScene==AURA_SUN_HAPPY && elapsed>=1800) {
    auraScene=AURA_IDLE; auraLastActivity=now; lastFace=-1; return;
  } else if (auraScene==AURA_TALK && elapsed>=1400) {
    auraScene=AURA_IDLE; lastFace=-1; return;
  } else if ((auraScene==AURA_WINK || auraScene==AURA_LOOK || auraScene==AURA_THINK ||
              auraScene==AURA_WIGGLE || auraScene==AURA_EXCITED) && elapsed>=1200) {
    auraScene=AURA_IDLE; lastFace=-1; return;
  }
  if (auraLastFrame!=0 && now-auraLastFrame<100) return; // non-blocking 10fps max
  auraLastFrame=now;
  switch(auraScene) {
    case AURA_WATER_FILL:
      auraRenderArt(0,1,1,(uint16_t)((elapsed*1000UL)/AURA_FILL_MS));break;
    case AURA_WATER_HOLD:
      auraRenderArt(0,3,2,1000);break;
    case AURA_WATER_DRAIN:
      auraRenderArt(0,1,1,(uint16_t)(1000-(elapsed*1000UL)/AURA_DRAIN_MS));break;
    case AURA_SUN_RAY:
      auraRenderArt(4,0,3,200);break;
    case AURA_SUN_GROW:
      auraRenderArt(1,0,3,(uint16_t)(330+(elapsed*390UL)/1100));break;
    case AURA_SUN_HAPPY:
      auraRenderArt(0,0,3,1000);break;
    case AURA_TALK:
      auraRenderArt(0,0,5);break;
    case AURA_WINK:
      auraRenderArt(auraSceneFace,2);break;
    case AURA_LOOK:
      auraRenderArt(auraSceneFace,4,0,0,(now/300)%4);break;
    case AURA_THINK:
      auraRenderArt(1,2,6);break;
    case AURA_WIGGLE:
      auraRenderArt(auraSceneFace,1,4);break;
    case AURA_EXCITED:
      auraRenderArt(0,3);break;
    case AURA_SLEEP:
      auraRenderArt(1,5,7);break;
    default:break;
  }
}

#endif  // AURA_APPROVED_ART_H
